LOGIC_BASIC = 0
LOGIC_ADVANCED = 1
LOGIC_CHAOS = 2
NEVER = 9999999

COMP_UPGRADEABLE = 1
COMP_COMPETENT = 2
COMP_ULTIMATE = 3
AA_ANY = 1
AA_BASIC = 2
AA_COMPETENT = 3
AA_VARIABLE = -1
"""Resolves to an AA rating based on logic level."""
HERO_BASIC = 1
HERO_COMPETENT = 2
DETECTION_BASIC = 2
DETECTION_MOBILE = 3

FLAG_NO_LOGIC_TRACKS = 0b1
"""This location has no track logic; it may still have a manual rule or minimum level"""

MAX_UNITS_REQUIRED = 5
MASTERY_LOCATION_UNITS_REQUIRED = 6
DEPTH_0_FREE_DEFENSE_RATING = 1
ADVANCED_FREE_DEFENSE_RATING = 2
ADVANCED_FREE_MACRO_RATING = 2


def max2(a: int, b: int) -> int:
    if a < b:
        return b
    return a


def resolve_aa(aa_min: int, logic_level: int) -> int:
    if aa_min >= 0:
        return aa_min
    if logic_level == LOGIC_BASIC:
        return AA_COMPETENT
    if logic_level == LOGIC_ADVANCED:
        return AA_BASIC
    return AA_ANY


class RuleSignature(NamedTuple):
    race: SC2Race
    logic_level: int = 0
    """0=standard, 1=advanced, 2=any_units"""
    num_units: int = 0
    anti_air: int = 0
    """1=any, 2=basic, 3=competent"""
    upgrades: int = 0
    power_comp: int = COMP_UPGRADEABLE
    """1=upgradeable unit, 2=competent comp, 3=ultimate comp"""
    macro_rating: int = 0
    """Rating out of 12. (Options and inventories reach higher ratings)."""
    soa_flags: int = 0
    defense_rating: int = 0
    """Rating out of 10."""
    detection: int = 0
    """1=precision ability, 2=any detector, 3=mobile detector"""
    artanis: int = 0
    nova: int = 0
    kerrigan: int = 0
    rule: Callable[[SC2Logic, 'CollectionState'], bool] | None = None

    def estimate_items_required(self, items_per_wa_upgrade: int) -> int:
        return (
            self.num_units
            + (2 if self.anti_air == AA_COMPETENT else 1 if self.anti_air else 0)
            + (items_per_wa_upgrade * self.upgrades)
            + (self.power_comp + 1 if self.power_comp > COMP_UPGRADEABLE else 0)
            + (self.macro_rating // 2)
            + (self.defense_rating)
            # Some defense ratings require item combos
            + (self.defense_rating > 0)
            + (self.detection > 0)
            + self.nova
            + self.artanis
            + self.kerrigan
            + (1 if self.rule is not None else 0)
        )

    @overload
    def resolve(
        self, logic: SC2Logic, default: Callable[['CollectionState'], bool]
    ) -> Callable[['CollectionState'], bool]: ...

    @overload
    def resolve(
        self, logic: SC2Logic, default: Callable[['CollectionState'], bool] | None
    ) -> Callable[['CollectionState'], bool] | None: ...

    def resolve(
        self, logic: SC2Logic, default=Callable[['CollectionState'], bool] | None
    ) -> Callable[['CollectionState'], bool] | None:
        parts: list[Callable[['CollectionState'], bool]] = []
        addon: Callable[['CollectionState'], bool]
        if self.num_units > 0:
            addon = logic.has_race_units(self.num_units, self.race, self.logic_level)
            parts.append(addon)
        if self.upgrades > 0 or self.power_comp > COMP_UPGRADEABLE:
            addon = logic.has_power_comp(self.race, self.upgrades, self.power_comp)
            parts.append(addon)
        if self.anti_air > 0:
            addon = logic.series_functions[LogicSeries.AntiAir, self.race, self.anti_air]
            parts.append(addon)
        if self.detection > 0:
            addon = logic.series_functions[LogicSeries.Detection, self.race, self.detection]
            parts.append(addon)
        if self.macro_rating > 0:
            addon = logic.get_rating_function(
                self.race, LogicSeries.MacroPower, self.macro_rating, self.soa_flags
            )
            parts.append(addon)
        if self.defense_rating > 0:
            addon = logic.get_rating_function(self.race, LogicSeries.DefenseRating, self.defense_rating)
            parts.append(addon)

        if self.artanis > 0:
            addon = logic.series_functions[LogicSeries.Artanis, SC2Race.ANY, self.artanis]
            parts.append(addon)
        if self.nova > 0:
            addon = logic.series_functions[LogicSeries.Nova, SC2Race.ANY, self.nova]
            parts.append(addon)
        if self.kerrigan > 0:
            addon = logic.series_functions[LogicSeries.Kerrigan, SC2Race.ANY, self.kerrigan]
            parts.append(addon)

        if self.rule is not None:
            addon = logic.name_to_function[self.rule.__name__]
            parts.append(addon)

        if not parts:
            return default
        result = rule_helpers.COUNT_TO_AND_FUNCTION[len(parts)](*parts)
        return result

    def __str__(self) -> str:
        fields = [
            f'{f}={self[index]}'
            for index, f in enumerate(self._fields[:-1])
            if self[index] and (f != "power_comp" or self[index] > COMP_UPGRADEABLE)]
        if self.rule:
            fields.append(f'rule={self.rule.__name__}')
        return f"RuleSignature({', '.join(fields)})"


NO_LOGIC_RULE_SIGNATURE = RuleSignature(SC2Race.ANY)


@dataclass(slots=True, kw_only=True)
class ProtoRule:
    upgrades_min: int = 0
    comp_type: int = COMP_UPGRADEABLE
    aa_min: int = 0
    macro_rating: int = 0
    """Rating out of 12"""
    defense_rating: int = 0
    """Rating out of 10, static defenses and base improvements"""
    hero_min: int = 0
    detection: int = 0
    flags: int = 0
    rule: Callable[[SC2Logic, 'CollectionState'], bool] | None = None
    basic_rule: Callable[[SC2Logic, 'CollectionState'], bool] | None = None
    hard_rule: Callable[[SC2Logic, 'CollectionState'], bool] | None = None

    def __post_init__(self) -> None:
        if self.rule is None:
            self.rule = self.hard_rule
        if self.basic_rule is None:
            self.basic_rule = self.rule

    @staticmethod
    def rating_from_progress(progress: float, thresholds: tuple[int, ...]) -> int:
        for index, threshold in enumerate(reversed(thresholds)):
            if progress >= threshold:
                return len(thresholds) - index
        return 0

    def to_signature(
        self,
        world: 'SC2World',
        mission: SC2Mission,
        location: Sc2Location,
        depth: int,
        order: int,
        hero_presence: dict[SC2Mission, HeroFlag],
        first_location: bool = False
    ) -> RuleSignature:
        if first_location:
            assert location.type != LocationType.MASTERY
            assert depth == 0

        # rough rating of completed missions normalized for narrower mission orders to progress slower
        if depth == 0:
            progress = order * 0.8
        else:
            progress = order - depth * 0.2
        logic_level = int(world.options.required_tactics)
        anti_air_depths: tuple[int, ...]
        upgrade_depths: tuple[int, ...]
        hero_depths: tuple[int, ...]
        if logic_level == LOGIC_BASIC:
            anti_air_depths = (5, 5, 11)
            upgrade_depths = (6, 10, 16)
            hero_depths = (2, 7, 20)
        elif logic_level == LOGIC_ADVANCED:
            anti_air_depths = (5, 5, 13)
            upgrade_depths = (6, 12, 18)
            hero_depths = (2, 8, 22)
        else:  # LOGIC_CHAOS
            anti_air_depths = (5,)
            upgrade_depths = (6, 13, 20)
            hero_depths = (3, 14)

        soa_flags = 0
        defense_rating = 0
        macro_rating = 0
        comp_type = COMP_UPGRADEABLE
        if mission.flags & MissionFlag.NoBuild or first_location:
            num_units = 0
            anti_air = 0
            upgrades = 0
            detection = 0
        else:
            num_units = depth or 1
            if location.type == LocationType.CHALLENGE:
                num_units += 1
            if num_units > MAX_UNITS_REQUIRED:
                num_units = MAX_UNITS_REQUIRED
            if logic_level < LOGIC_CHAOS:
                comp_type = self.comp_type
            detection = self.detection
            if not (FLAG_NO_LOGIC_TRACKS & self.flags):
                anti_air = self.rating_from_progress(progress, anti_air_depths)
                upgrades = self.rating_from_progress(progress, upgrade_depths)
            else:
                anti_air = 0
                upgrades = 0
                num_units = 0
            aa_min = resolve_aa(self.aa_min, logic_level)
            anti_air = max2(anti_air, aa_min)
            if logic_level == LOGIC_CHAOS and anti_air > 1:
                anti_air = 1
            upgrades = max2(upgrades, self.upgrades_min)
            if location.type == LocationType.MASTERY:
                num_units = MASTERY_LOCATION_UNITS_REQUIRED
                upgrades = max(upgrades, 3)
            soa_flags = (
                options.is_mission_in_soa_presence(
                    world.options.spear_of_adun_presence.value, mission, options.SpearOfAdunPresence,
                )
                | options.is_mission_in_soa_presence(
                    world.options.spear_of_adun_passive_ability_presence.value,
                    mission,
                    options.SpearOfAdunPassiveAbilityPresence,
                ) << 1
            )
            if logic_level == LOGIC_BASIC:
                defense_rating = self.defense_rating
                macro_rating = self.macro_rating
            elif logic_level == LOGIC_ADVANCED:
                defense_rating = max2(0, self.defense_rating - ADVANCED_FREE_DEFENSE_RATING)
                macro_rating = max2(0, self.macro_rating - ADVANCED_FREE_MACRO_RATING)
            if depth == 0:
                defense_rating -= DEPTH_0_FREE_DEFENSE_RATING
                defense_rating = max2(0, defense_rating)

        # Heroes
        required_hero_rating = 0
        if first_location or MissionFlag.NoBuild in mission.flags:
            pass
        else:
            if not (FLAG_NO_LOGIC_TRACKS & self.flags):
                required_hero_rating = self.rating_from_progress(depth, hero_depths)
            required_hero_rating = max(self.hero_min, required_hero_rating)
            if mission in world.logic.grant_hero_items:
                required_hero_rating = 0
        if MissionFlag.HeroSystemUnsupported & mission.flags:
            # Hero requirements assumed captured by manual rules; grant story tech usually applies
            heroes = HeroFlag.NONE
        else:
            heroes = hero_presence.get(mission, HeroFlag.NONE)

        if heroes:
            defense_rating = max2(0, defense_rating - required_hero_rating)

        return RuleSignature(
            mission.race,
            logic_level,
            num_units,
            anti_air,
            upgrades,
            comp_type,
            macro_rating,
            soa_flags,
            defense_rating,
            detection,
            artanis=required_hero_rating if HeroFlag.ARTANIS in heroes else 0,
            nova=required_hero_rating if HeroFlag.NOVA in heroes else 0,
            kerrigan=required_hero_rating if HeroFlag.KERRIGAN in heroes else 0,
            rule=(
                self.basic_rule if logic_level == LOGIC_BASIC else
                self.rule if logic_level == LOGIC_ADVANCED else
                self.hard_rule
            )
        )


